function esc(s) { return s.replace(/'/g, "\\'"); }

function entry(n, la, ln, sub, desc, fact) {
  return `  {n:'${esc(n)}',la:${la},ln:${ln},sub:'${esc(sub)}',desc:'${esc(desc)}',fact:'${esc(fact)}'},`;
}

